Please add a deterministic test that uses tokio::test and a fake server implemented with tokio_tungstenite::accept_async to simulate abrupt close after handshake. Provide sample test harness and SDK usage:

// tests/ws_reconnect.rs
#[tokio::test]
async fn reconnects_and_cleans_up() {
    let (tx, rx) = tokio::sync::oneshot::channel();
    let server = tokio::spawn(async move {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        tx.send(listener.local_addr().unwrap()).unwrap();
        let (stream, _) = listener.accept().await.unwrap();
        let ws = tokio_tungstenite::accept_async(stream).await.unwrap();
        drop(ws); // close immediately
    });

    let addr = rx.await.unwrap();
    let client = SdkClient::connect(format!("ws://{}", addr)).await.unwrap();
    client.wait_for_reconnects(2).await;
    assert_eq!(active_task_count(), 0);
}

Make sure tests assert no leaked tasks after client shutdown.

